<?php
include_once 'db_connect.php';$school=(int)($_SESSION['login_school_id']??0);$years=[];$activeYear=0;$stmt=$conn->prepare('SELECT id,year,is_active FROM academic_year WHERE school_id=? ORDER BY year DESC');$stmt->bind_param('i',$school);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc()){$years[]=$x;if((int)$x['is_active']===1)$activeYear=(int)$x['id'];}$stmt->close();$students=[];$stmt=$conn->prepare('SELECT id,id_no,name FROM student WHERE school_id=? ORDER BY name');$stmt->bind_param('i',$school);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$students[]=$x;$stmt->close();$courses=[];$stmt=$conn->prepare('SELECT c.id,c.course,c.level,ay.year FROM courses c LEFT JOIN academic_year ay ON ay.id=c.academic_year_id WHERE ay.school_id=? ORDER BY ay.year DESC,c.course');$stmt->bind_param('i',$school);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$courses[]=$x;$stmt->close();
?>
