ncer">Por vencer</option></select></div><div><label>Estado de deuda</label><select id="dr-debt-status" class="form-control form-control-sm"><option value="Activa" selected>Activa</option><option>Suspendida</option><option>Anulada</option><option value="">Todos</option></select></div><div><label>Estado del estudiante</label><select id="dr-student-status" class="form-control form-control-sm"><option value="">Todos</option><option>Activo</option><option>Retirado</option><option>Egresado</option></select></div><div><label>Filtrar fechas por</label><select id="dr-date-type" class="form-control form-control-sm"><option value="assignment">Asignación</option><option value="due">Vencimiento</option><option value="payment">Pago confirmado</option></select></div><div><label>Desde</label><input id="dr-from" type="date" class="form-control form-control-sm"></div><div><label>Hasta</label><input id="dr-to" type="date" class="form-control form-control-sm"></div><div class="d-flex align-items-end"><button id="dr-apply" class="btn btn-primary btn-sm mr-2"><i class="fas fa-filter mr-1"></i>Aplicar</button><button id="dr-clear" class="btn btn-light border btn-sm">Restablecer</button></div></div></div>
