<script>
$(function(){
const activeYear=<?php echo (int)$activeYear; ?>,gradeMap={Inicial:['3 años','4 años','5 años'],Primaria:['1°','2°','3°','4°','5°','6°'],Secundaria:['1°','2°','3°','4°','5°']};
if($.fn.select2)$('.dr-select2').select2({width:'100%'});
function loadGrades(value){let level=$('#dr-level').val(),grades=gradeMap[level]||[],select=$('#dr-grade').empty();if(!level){select.append('<option value="">Seleccione un nivel</option>').prop('disabled',true);return}select.append('<option value="">Todos</option>');grades.forEach(g=>select.append(new Option(g,g)));select.prop('disabled',false);if(value&&grades.indexOf(value)>=0)select.val(value)}
$('#dr-level').on('change',function(){loadGrades('')});loadGrades('');
function filters(){return{academic_year_id:$('#dr-year').val(),nivel:$('#dr-level').val(),grado:$('#dr-grade').val(),seccion:$('#dr-section').val(),student_id:$('#dr-student').val(),concepto:$('#dr-course').val(),financial_status:$('#dr-financial').val(),debt_status:$('#dr-debt-status').val(),student_status:$('#dr-student-status').val(),date_type:$('#dr-date-type').val(),start_date:$('#dr-from').val(),end_date:$('#dr-to').val()}}
function money(v){return'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})}
function esc(v){return $('<div>').text(v==null?'':v).html()}
let table=null,view='detail';
const configs={
 detail:{heads:['Estudiante','Concepto','Año','Original','Exigible','Pagado','Saldo','Vencimiento','Estado financiero / deuda'],cols:Array.from({length:9},(_,i)=>({data:i,orderable:i!==1}))},
 student:{heads:['Estudiante','Aula','Deudas','Original','Descuentos','Exigible','Pagado','Saldo','Saldo vencido'],cols:[
  {data:null,render:r=>'<strong>'+esc(r.student_name)+'</strong><div class="small text-muted">'+esc(r.id_no)+'</div>'},
  {data:null,render:r=>esc(r.nivel+' · '+r.grado+' '+r.seccion)},
  {data:'debts'},{data:'original_amount',render:money},{data:'discount_amount',render:money},{data:'effective_amount',render:money},{data:'paid_amount',render:money},{data:'balance',render:money},{data:'overdue_amount',render:money}
 ]},
 concept:{heads:['Concepto','Año','Deudas','Estudiantes','Original','Exigible','Pagado','Saldo','Saldo vencido'],cols:[
  {data:'concept_name',render:v=>'<strong>'+esc(v)+'</strong>'},{data:'academic_year',defaultContent:'—'},{data:'debts'},{data:'students'},{data:'original_amount',render:money},{data:'effective_amount',render:money},{data:'paid_amount',render:money},{data:'balance',render:money},{data:'overdue_amount',render:money}
 ]},
 classroom:{heads:['Nivel','Grado','Sección','Estudiantes','Deudas','Exigible','Pagado','Saldo','Saldo vencido'],cols:[
  {data:'nivel'},{data:'grado'},{data:'seccion'},{data:'students'},{data:'debts'},{data:'effective_amount',render:money},{data:'paid_amount',render:money},{data:'balance',render:money},{data:'overdue_amount',render:money}
 ]},
 state:{heads:['Estado financiero','Estado deuda','Deudas','Estudiantes','Exigible','Pagado','Saldo','Saldo vencido'],cols:[
  {data:'financial_state',render:v=>'<strong>'+esc(v)+'</strong>'},{data:'debt_status'},{data:'debts'},{data:'students'},{data:'effective_amount',render:money},{data:'paid_amount',render:money},{data:'balance',render:money},{data:'overdue_amount',render:money}
 ]}
};
function updateSummary(json){let s=json.summary||{};$('#dr-original').text(money(s.original));$('#dr-discounts').text(money(s.discounts));$('#dr-effective').text(money(s.effective));$('#dr-collected').text(money(s.collected));$('#dr-balance').text(money(s.balance));$('#dr-overdue').text(money(s.overdue))}
function initTable(){let c=configs[view];if(table){table.destroy();$('#debt-reports-table').empty()}$('#debt-reports-table').append('<thead><tr>'+c.heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody></tbody>');table=$('#debt-reports-table').DataTable({serverSide:true,processing:true,pageLength:25,lengthMenu:[[25,50,100],[25,50,100]],order:[],ajax:{url:'api/debt_reports.php',data:function(d){return $.extend(d,filters(),{view:view})},dataSrc:function(json){$('#dr-error').addClass('d-none');updateSummary(json);return json.data||[]},error:function(xhr){let m='No se pudo cargar el reporte.';try{let j=JSON.parse(xhr.responseText);m=j.error||j.message||m}catch(e){}$('#dr-error').removeClass('d-none').text(m)}},columns:c.cols,language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_',processing:'Cargando deudas...',zeroRecords:'No se encontraron registros con los filtros seleccionados',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Sin registros',paginate:{previous:'Anterior',next:'Siguiente'}}})}
$('#dr-apply').click(function(){table&&table.ajax.reload()});
$('#dr-clear').click(function(){$('.dr-filters input').val('');$('.dr-filters select').val('').trigger('change');$('#dr-year').val(String(activeYear));$('#dr-financial').val('Todas');$('#dr-debt-status').val('Activa');$('#dr-date-type').val('assignment');loadGrades('');table&&table.search('').ajax.reload()});
const viewHelp={detail:'Cada fila representa una deuda asignada.',student:'Totales consolidados por estudiante.',concept:'Deuda agrupada por concepto de pago.',classroom:'Saldo consolidado por nivel, grado y sección.',state:'Distribución por estado financiero y estado de la deuda.'};
$('.dr-tabs button').on('click',function(){view=$(this).data('view');$('.dr-tabs button').removeClass('btn-primary').addClass('btn-outline-primary');$(this).addClass('btn-primary').removeClass('btn-outline-primary');$('#dr-view-help').text(viewHelp[view]||'');initTable()});
initTable();
function query(){return $.param($.extend({},filters(),{view:view}))}$('#dr-export').click(function(){location.href='export_debt_report.php?'+query()});$('#dr-print').click(function(){let frame=$('#dr-print-frame');$('#dr-print-loading').removeClass('d-none').addClass('d-flex');frame.hide().off('load.dr').on('load.dr',function(){$('#dr-print-loading').removeClass('d-flex').addClass('d-none');frame.show()}).attr('src','print_debt_report.php?'+query());$('#debt-print-modal').modal('show')});$('#debt-print-modal').on('hidden.bs.modal',function(){$('#dr-print-frame').attr('src','about:blank').hide()});
});
</script>
